create index if not exists idx_audit_user_created on audit_logs(user_id,created_at desc); create index if not exists idx_alloc_lot on transaction_allocations(lot_id,created_at desc); create index if not exists idx_lots_user_due on lots(user_id,hawl_due_date) where remaining_quantity>0; create index if not exists idx_assess_user_status on zakat_assessments(user_id,status);
create or replace function public.schedule_hawl_notifications(p_user uuid) returns integer language plpgsql security invoker as $$ declare r record; n integer:=0; d integer; v_ts timestamptz; begin for r in select id,hawl_due_date from lots where user_id=p_user and remaining_quantity>0 and hawl_due_date is not null loop foreach d in array ARRAY[30,15,7]::integer[] loop v_ts:=(r.hawl_due_date-make_interval(days=>d))::timestamptz; insert into notification_jobs(user_id,notification_type,scheduled_for) values(p_user,'HAWL_DUE_'||d,v_ts) on conflict do nothing; n:=n+1; end loop; end loop; return n; end; $$;
create policy audit_insert_self on audit_logs for insert with check(user_id=auth.uid());
create policy prices_insert_restricted on market_prices for insert with check(auth.uid() is not null and exists(select 1 from profiles where id=auth.uid() and role in ('ADMIN','ACCOUNTANT','SHARIA_REVIEWER')));
create policy fx_insert_restricted on fx_rates for insert with check(auth.uid() is not null and exists(select 1 from profiles where id=auth.uid() and role in ('ADMIN','ACCOUNTANT','SHARIA_REVIEWER')));
create policy sharia_reviews_read on sharia_rule_reviews for select using(exists(select 1 from zakat_rules r where r.id=rule_id and r.review_status='APPROVED') or reviewer_id=auth.uid());
create policy rule_sources_read on rule_sources for select using(exists(select 1 from zakat_rules r where r.id=rule_id and r.review_status='APPROVED'));
create policy notification_jobs_self on notification_jobs for select using(user_id=auth.uid());
create policy provider_configs_admin on price_provider_configs for select using(exists(select 1 from profiles where id=auth.uid() and role in ('ADMIN','SHARIA_REVIEWER')));